// End-to-end harness: starts the real Relay (a built relay.exe) on a
// throwaway data folder with WebView2 remote debugging (RELAY_DEVTOOLS_PORT),
// and drives its two windows (the main one and the player) over the Chrome
// DevTools Protocol: clicking the pages' own buttons, reading
// `window.__relay` (each window's UI store) and calling commands directly
// where the UI would open a native dialog.
//
// A new library starts empty, so the folder starts with the design's four
// samples (`samples.json`, generated by relay-core's tests) and with the
// first run done, unless a test asks otherwise.
//
// It never synthesizes OS input: the tests only use the page's DOM and
// Relay's commands. Macros that are played contain only waits and pixel
// checks, so playback sends nothing to the desktop either.
import { spawn, execFileSync } from "node:child_process";
import { mkdtempSync, rmSync, existsSync, readFileSync, readdirSync, writeFileSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { randomUUID } from "node:crypto";

const ROOT = resolve(import.meta.dirname, "..");
/** The design's four samples, as .rly documents. */
export const SAMPLES = JSON.parse(readFileSync(join(import.meta.dirname, "samples.json"), "utf8"));
/** A new install's keys (settings.rs RelayKeys::new_default). */
export const KEYS = { record: "Ctrl + Shift + F9", play: "Ctrl + Shift + F10", player: "Ctrl + Shift + M", kill: "Ctrl + Alt + Backspace" };
export const EXE = resolve(process.env.RELAY_EXE ?? join(ROOT, "target", "debug", "relay.exe"));

export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Polls `check` until it returns something truthy, or fails after `timeout` ms. */
export async function until(check, { timeout = 10_000, every = 100, what = "condition" } = {}) {
  const end = Date.now() + timeout;
  let last;
  for (;;) {
    try {
      last = await check();
      if (last) return last;
    } catch (e) {
      if (e?.fatal) throw e;
      last = e;
    }
    if (Date.now() > end) throw new Error(`timed out waiting for ${what} (last: ${last instanceof Error ? last.message : JSON.stringify(last)})`);
    await sleep(every);
  }
}

function relayRunning() {
  try {
    const out = execFileSync("tasklist", ["/FI", "IMAGENAME eq relay.exe", "/FO", "CSV", "/NH"], { encoding: "utf8" });
    return out.toLowerCase().includes("relay.exe");
  } catch {
    return false;
  }
}

/** A Chrome DevTools Protocol session with the page. */
class Page {
  constructor(ws) {
    this.ws = ws;
    this.id = 0;
    this.pending = new Map();
    ws.addEventListener("message", (ev) => {
      const msg = JSON.parse(ev.data);
      const p = this.pending.get(msg.id);
      if (p) {
        this.pending.delete(msg.id);
        p.resolve(msg);
      }
    });
    // The page went away (Relay quit or crashed): nothing pending will be answered.
    ws.addEventListener("close", () => {
      for (const p of this.pending.values()) p.reject(new Error("the page closed"));
      this.pending.clear();
    });
  }

  /** A DevTools call; fails after `timeout` ms rather than hanging a run. */
  send(method, params = {}, timeout = 30_000) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        reject(new Error(`${method} got no answer in ${timeout} ms`));
      }, timeout);
      const done = (f) => (v) => {
        clearTimeout(timer);
        f(v);
      };
      this.pending.set(id, { resolve: done(resolve), reject: done(reject) });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }

  /** Runs `fn(...args)` in the page (it may be async) and returns its JSON result. */
  async run(fn, ...args) {
    const expression = `(${fn})(...${JSON.stringify(args)})`;
    const res = await this.send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
    if (res.error) throw new Error(`DevTools: ${res.error.message}`);
    const r = res.result;
    if (r?.exceptionDetails) {
      throw new Error("in page: " + (r.exceptionDetails.exception?.description ?? r.exceptionDetails.text));
    }
    return r?.result?.value;
  }

  /** A command, as the UI would send it. Rejections come back as `{ code, message }`. */
  invoke(cmd, args = {}) {
    return this.run(
      async (cmd, args) => {
        try {
          return { ok: await window.__TAURI_INTERNALS__.invoke(cmd, args) };
        } catch (e) {
          return { err: e };
        }
      },
      cmd,
      args,
    ).then((r) => {
      if (r && "err" in r) throw Object.assign(new Error(r.err?.message ?? String(r.err)), { code: r.err?.code });
      return r?.ok;
    });
  }

  /** Reads the store: `page.store("mode")`, `page.store("view.name")`. */
  store(path) {
    return this.run((path) => path.split(".").reduce((o, k) => o?.[k], window.__relay), path);
  }

  /**
   * Clicks the one visible button (or tab, switch, radio…) with exactly this
   * accessible name, like `getByRole`. Fails if there's none, more than one
   * (unless `nth` picks one, in page order), or it's disabled.
   */
  click(name, { role, within, nth } = {}) {
    return this.run(
      (name, role, within, nth) => {
        const root = within ? document.querySelector(within) : document;
        if (!root) throw new Error(`no ${within}`);
        const label = (el) =>
          (
            el.getAttribute("aria-label") ??
            document.getElementById(el.getAttribute("aria-labelledby"))?.textContent ??
            el.querySelector(":scope > .text")?.textContent ??
            el.textContent ??
            ""
          )
            .replace(/\s+/g, " ")
            .trim();
        const selector = role ? `[role="${role}"]` : 'button, [role="button"], [role="tab"], [role="switch"], [role="radio"]';
        const matches = [...root.querySelectorAll(selector)].filter((c) => label(c) === name && c.getClientRects().length > 0);
        if (matches.length === 0) throw new Error(`no control named “${name}”`);
        if (matches.length > 1 && nth == null) throw new Error(`${matches.length} controls are named “${name}”`);
        const el = matches[nth ?? 0];
        if (!el) throw new Error(`no control #${nth} named “${name}”`);
        if (el.disabled || el.getAttribute("aria-disabled") === "true") throw new Error(`“${name}” is disabled`);
        el.click();
        return true;
      },
      name,
      role ?? null,
      within ?? null,
      nth ?? null,
    );
  }

  /** Opens the menu of the button named `opener` and chooses `item` in it. */
  async menu(opener, item, options = {}) {
    await this.click(opener, options);
    await until(() => this.run(() => !!document.querySelector('[role="menu"]')), { what: `the ${opener} menu` });
    const role = await this.run((item) => {
      const it = [...document.querySelectorAll('[role="menu"] [role^="menuitem"]')].find(
        (el) => el.querySelector(".text")?.textContent.trim() === item,
      );
      return it?.getAttribute("role") ?? "menuitem";
    }, item);
    return this.click(item, { role });
  }

  /** Chooses `item` in the Library row's menu (… More for the macro). */
  rowAction(item, macroName) {
    return this.menu(`More for ${macroName}`, item);
  }

  /** Adds a step (Wait, Text, Wait for pixel, Find image) at the insertion line. */
  addStep(kind) {
    return this.menu("Add", kind, { within: ".steps" });
  }

  /**
   * Sets an inspector field, by its name ("Waits", "Label", "Color"…), and
   * commits it as leaving the field does.
   */
  setField(name, value) {
    return this.run(
      (name, value) => {
        const named = (el) => {
          const a = el.getAttribute("aria-label");
          if (a) return a === name || a.startsWith(`${name} in `);
          return !!el.id && document.querySelector(`label[for="${el.id}"]`)?.textContent.trim() === name;
        };
        const el = [...document.querySelectorAll(".inspector input, .inspector textarea")].find(named);
        if (!el) throw new Error(`no field ${name}`);
        el.value = value;
        el.dispatchEvent(new Event("input", { bubbles: true }));
        el.dispatchEvent(new Event("change", { bubbles: true }));
        return true;
      },
      name,
      value,
    );
  }

  /**
   * Clicks Play and times the run inside the page (no round trips in the
   * measurement): `ms` from playing to idle, and `from`, the playhead when
   * playing began. `timing` says where the time went, for failure messages.
   */
  playTimed({ timeout = 20_000 } = {}) {
    return this.run(async (timeout) => {
      const r = window.__relay;
      let moved = 0;
      let last = r.cur;
      const until = async (ok) => {
        const end = performance.now() + timeout;
        while (!ok()) {
          if (performance.now() > end) throw new Error(`still ${r.mode}`);
          await new Promise((res) => setTimeout(res, 2));
          if (r.cur !== last) [last, moved] = [r.cur, performance.now()];
        }
        return performance.now();
      };
      const play = [...document.querySelectorAll("button")].find((b) => b.getAttribute("aria-label") === "Play");
      if (!play || play.disabled) throw new Error("no Play button to click");
      const clicked = performance.now();
      play.click();
      const started = await until(() => r.mode === "playing");
      const from = r.cur;
      const ended = await until(() => r.mode === "idle");
      const at = (t) => Math.round(Math.max(t, started) - started);
      const timing = `playing after ${Math.round(started - clicked)} ms; playhead last moved at ${at(moved)} ms; idle at ${at(ended)} ms`;
      return { ms: ended - started, from, finish: r.lastFinish, timing };
    }, timeout);
  }

  /** Goes to a place in the window (library, macro, settings) and waits until it shows. */
  async go(place) {
    await this.run((place) => window.__relay.go(place), place);
    await until(() => this.run((place) => document.querySelector(".app-window")?.dataset.place === place, place), {
      what: `the ${place}`,
    });
  }

  /** Opens a macro in the editor (as a Library click does) and waits until it shows. */
  async open(id) {
    await this.run((id) => window.__relay.openMacro(id), id);
    await until(async () => (await this.store("view.id")) === id && (await this.store("place")) === "macro", {
      what: "the macro to open",
    });
  }

  /** Shows the inspector's Step or Macro tab (and in Macro, its Play or Triggers section). */
  async inspector(tab, section) {
    await this.run(
      (tab, section) => {
        const r = window.__relay;
        r.inspector = tab;
        r.inspectorOpen = true;
        if (section) r.macroSection = section;
        return true;
      },
      tab,
      section ?? null,
    );
    await this.idle();
  }

  /** Selects step `i` in the list, as a click on its row does; the Step tab shows it. */
  async selectStep(i) {
    await this.run((i) => {
      window.__relay.select([i]);
      return true;
    }, i);
    await this.inspector("step");
  }

  /** Whether the control with exactly this name (inside `within`, if given) is disabled (it must exist). */
  disabled(name, { role, within } = {}) {
    return this.run(
      (name, role, within) => {
        const root = within ? document.querySelector(within) : document;
        if (!root) throw new Error(`no ${within}`);
        const label = (el) =>
          (
            el.getAttribute("aria-label") ??
            document.getElementById(el.getAttribute("aria-labelledby"))?.textContent ??
            el.querySelector(":scope > .text")?.textContent ??
            el.textContent ??
            ""
          )
            .replace(/\s+/g, " ")
            .trim();
        const selector = role ? `[role="${role}"]` : 'button, [role="button"], [role="tab"], [role="switch"], [role="radio"]';
        const el = [...root.querySelectorAll(selector)].find((c) => label(c) === name);
        if (!el) throw new Error(`no control named “${name}”`);
        return el.disabled || el.getAttribute("aria-disabled") === "true";
      },
      name,
      role ?? null,
      within ?? null,
    );
  }

  /** Sets an input's value and fires the events Svelte listens to. */
  fill(selector, value) {
    return this.run(
      (selector, value) => {
        const el = document.querySelector(selector);
        if (!el) throw new Error(`no ${selector}`);
        el.value = value;
        el.dispatchEvent(new Event("input", { bubbles: true }));
        el.dispatchEvent(new Event("change", { bubbles: true }));
        return true;
      },
      selector,
      value,
    );
  }

  text(selector = "body") {
    return this.run((s) => document.querySelector(s)?.innerText ?? null, selector);
  }

  /** Waits until the store's `mode` is `mode`. */
  waitMode(mode, timeout = 10_000) {
    return until(async () => (await this.store("mode")) === mode, { timeout, what: `mode ${mode}` });
  }

  /** Waits for the UI to settle (pending commands answered, a frame drawn). */
  idle(ms = 150) {
    return this.run((ms) => new Promise((r) => setTimeout(() => requestAnimationFrame(() => r(true)), ms)), ms);
  }

  /**
   * Back to a known state between tests: no session, the window rather than
   * the player (unless `keepPlayer`), no step selected, no message. A
   * failing test then doesn't leave its mess to the next one.
   */
  async reset({ keepPlayer = false } = {}) {
    if ((await this.store("mode")) !== "idle") {
      await this.invoke("stop_session");
      await this.waitMode("idle");
    }
    if (!keepPlayer && (await this.store("playerMode"))) await this.invoke("set_player_mode", { on: false });
    await this.run(() => {
      const r = window.__relay;
      r.exportOpen = false;
      r.select([]);
      r.clearToasts();
      return true;
    });
  }

  close() {
    this.ws.close();
  }
}

/**
 * Relay on a scratch data folder. `start()` launches it and connects;
 * `quit()` asks it to exit (as the tray's Quit does); `restart()` does both,
 * keeping the data, to check what survives.
 */
export class App {
  /**
   * `samples`: start with the design's four samples. `settings`: what
   * settings.json starts with (the first run done, a new install's keys);
   * `null` for none, as on a new install.
   */
  constructor({
    port = 9300 + Math.floor(Math.random() * 500),
    dir,
    samples = true,
    settings = { intro: "done", keys: KEYS },
  } = {}) {
    this.port = port;
    this.dir = dir ?? mkdtempSync(join(tmpdir(), "relay-e2e-"));
    this.proc = null;
    this.page = null;
    this.player = null;
    this.log = "";
    this.seed = { samples, settings };
  }

  path(...parts) {
    return join(this.dir, ...parts);
  }

  json(...parts) {
    return JSON.parse(readFileSync(this.path(...parts), "utf8"));
  }

  exists(...parts) {
    return existsSync(this.path(...parts));
  }

  macroFiles() {
    return existsSync(this.path("macros")) ? readdirSync(this.path("macros")).filter((f) => f.endsWith(".rly")) : [];
  }

  /** The macro as saved on disk. */
  macro(id) {
    return this.json("macros", `${id}.rly`);
  }

  writeSettings(settings) {
    mkdirSync(this.dir, { recursive: true });
    writeFileSync(this.path("settings.json"), JSON.stringify(settings));
  }

  /** The folder's first contents, before the first start. */
  seedFolder() {
    if (!this.seed) return;
    const { samples, settings } = this.seed;
    this.seed = null;
    if (samples && !existsSync(this.path("macros"))) {
      mkdirSync(this.path("macros"), { recursive: true });
      for (const m of SAMPLES) writeFileSync(this.path("macros", `${m.id}.rly`), JSON.stringify(m));
    }
    if (settings && !existsSync(this.path("settings.json"))) this.writeSettings(settings);
  }

  async start() {
    if (!existsSync(EXE)) throw new Error(`${EXE} doesn't exist: build it with \`npx tauri build --debug --no-bundle\``);
    this.seedFolder();
    if (relayRunning()) throw new Error("Relay is already running. Quit it first: Relay only runs once, so the test would reach it instead.");
    const env = {
      ...process.env,
      RELAY_DATA_DIR: this.dir,
      RELAY_DEVTOOLS_PORT: String(this.port),
    };
    this.proc = spawn(EXE, [], { env, stdio: ["ignore", "pipe", "pipe"], windowsHide: true });
    this.proc.stdout.on("data", (d) => (this.log += d));
    this.proc.stderr.on("data", (d) => (this.log += d));
    this.exitCode = null;
    this.exited = new Promise((r) => this.proc.once("exit", (code) => r((this.exitCode = code ?? -1))));

    let pages;
    try {
      pages = await until(
        async () => {
          if (this.exitCode != null) throw Object.assign(new Error(`Relay exited with code ${this.exitCode}`), { fatal: true });
          const targets = await (await fetch(`http://127.0.0.1:${this.port}/json`)).json();
          const found = targets.filter((t) => t.type === "page" && !t.url.startsWith("devtools"));
          return found.length >= 2 && found;
        },
        { timeout: 45_000, every: 250, what: "both windows' debugging targets" },
      );
    } catch (e) {
      throw new Error(`${e.message}\n${this.diagnostics()}`);
    }
    for (const target of pages) {
      const ws = new WebSocket(target.webSocketDebuggerUrl);
      await new Promise((r, j) => {
        ws.addEventListener("open", r, { once: true });
        ws.addEventListener("error", j, { once: true });
      });
      const page = new Page(ws);
      const label = await until(() => page.run(() => window.__TAURI_INTERNALS__?.metadata?.currentWindow?.label), {
        what: "the window's label",
      });
      if (label === "player") this.player = page;
      else this.page = page;
    }
    const loaded = () =>
      !!window.__relay?.ready &&
      !!document.querySelector(".app-window, .player") &&
      (window.__relay.library.length === 0 || !!window.__relay.view);
    for (const page of [this.page, this.player]) await until(() => page.run(loaded), { timeout: 20_000, what: "the UI to load" });
    await this.page.idle(300);
    return this.page;
  }

  /** Whether one of Relay's windows shows (Tauri's own view of it). */
  visible(label) {
    return this.page.invoke("plugin:window|is_visible", { label });
  }

  /** What Relay printed and logged, for a failure message. */
  diagnostics() {
    const tail = (text, n = 30) => text.trim().split(/\r?\n/).slice(-n).join("\n");
    let logs = "";
    try {
      for (const f of readdirSync(this.path("logs"))) logs += readFileSync(this.path("logs", f), "utf8");
    } catch {
      logs = "(no log folder)";
    }
    const state = this.exitCode == null ? "still running" : `exited with code ${this.exitCode}`;
    return `Relay ${state}.\n--- output ---\n${tail(this.log) || "(none)"}\n--- log ---\n${tail(logs) || "(empty)"}`;
  }

  async quit() {
    if (!this.proc) return;
    try {
      await Promise.race([this.page?.invoke("quit"), sleep(2000)]);
    } catch {
      // The page goes away as Relay exits.
    }
    this.page?.close();
    this.player?.close();
    const exited = await Promise.race([this.exited.then(() => true), sleep(8000).then(() => false)]);
    if (!exited) this.proc.kill();
    await this.exited;
    this.proc = null;
    this.page = null;
    this.player = null;
  }

  async restart() {
    await this.quit();
    return this.start();
  }

  /** Quits and deletes the scratch folder. */
  async dispose() {
    await this.quit();
    rmSync(this.dir, { recursive: true, force: true });
  }
}

const DESKTOP = { x: 0, y: 0, w: 1920, h: 1080 };

/**
 * A `.rly` document that only waits (and optionally checks a pixel), so
 * playing it sends no input to the desktop.
 */
export function waitingMacro({ name = "Just waits", waits = [1500], pixel = null, speed = 1, repeat = { count: 1 } } = {}) {
  const events = [];
  let t = 0;
  for (const dur of waits) {
    events.push({ type: "wait", t, dur, label: `Wait ${dur}` });
    t += dur;
  }
  if (pixel) events.push({ type: "pixel_wait", t, dur: 500, tolerance: 0, timeout_ms: 800, label: "Never matches", ...pixel });
  return {
    format: "relay-macro",
    version: 1,
    id: randomUUID(),
    name,
    created_at: "2026-09-26T10:00:00Z",
    modified_at: "2026-09-26T10:00:00Z",
    recording: {
      os: "windows",
      virtual_desktop: DESKTOP,
      monitors: [{ name: "\\\\.\\DISPLAY1", rect: DESKTOP, work: { ...DESKTOP, h: 1032 }, dpi: 96, primary: true }],
      double_click_ms: 500,
      double_click_px: 4,
    },
    // No humanize (exact timing) and no stop-on-key (a stray key press mustn't stop a test).
    playback: { speed, repeat, humanize: false, jitter_ms: 0, stop_on_key: false, coord_mode: "screen" },
    events,
  };
}

/** Writes `.rly` documents to a folder and returns their paths. */
export function writeRly(dir, docs) {
  mkdirSync(dir, { recursive: true });
  return docs.map((doc, i) => {
    const p = join(dir, `${i}-${doc.name ?? "file"}.rly`.replace(/[^\w.-]+/g, "_"));
    writeFileSync(p, typeof doc === "string" ? doc : JSON.stringify(doc));
    return p;
  });
}
